	@Test
	void aParallelWaveKeepsFilteredRootPopulationsAndCompleteRunBounds() throws Exception {
		LmdbNativeCostQuote serial = firstRow(2_999L, 3_000L).quote();
		int wave = 2 * LmdbNativePackedFtree.ROOT_BATCH_SIZE;
		LmdbNativeCostQuote.ChunkedWork construction = serial.chunked().scaled(0.5D, wave);
		assertThat(construction.rootCount()).isEqualTo(3_000D);
		assertThat(construction.acceptedRootCount()).isEqualTo(2D);
		assertThat(construction.batchSize()).isEqualTo(wave);
		assertThat(construction.rawRootWork()).isEqualTo(serial.chunked().rawRootWork().scale(0.5D));
		assertThat(construction.descendantWork()).isEqualTo(serial.chunked().descendantWork().scale(0.5D));
		assertThat(construction.vector().expected(Feature.OPEN))
				.isEqualTo(serial.chunked().vector().expected(Feature.OPEN));
		LmdbNativeCostQuote parallel = new LmdbNativeCostQuote(serial.startup(), serial.streaming().scale(0.5D),
				serial.outputRows(), false, false, construction);
		assertThat(parallel.forSlice(1D).high(Feature.SCANNED_ROW)).isEqualTo(1_506D);
		assertThat(parallel.forSlice(1D).expected(Feature.INDEX_SEEK)).isGreaterThanOrEqualTo(1D);
	}

