	private static NativeAdjacency adjacency(long predicate, int firstKey, int keyCount, boolean skewed,
			AtomicLong keys, AtomicLong binds, AtomicLong neighbors) {
		NativeAdjacency adjacency = mock(NativeAdjacency.class);
		when(adjacency.supportsKeyEnumeration()).thenReturn(true);
		when(adjacency.runsNeighborOrdered()).thenReturn(true);
		when(adjacency.keyCount()).thenReturn((long) keyCount);
		NativeAdjacency.KeyRunCursor keyCursor = mock(NativeAdjacency.KeyRunCursor.class);
		AtomicInteger nextKey = new AtomicInteger(firstKey);
		when(keyCursor.fillKeys(any(long[].class), anyInt(), anyInt())).thenAnswer(invocation -> {
			long[] target = invocation.getArgument(0);
			int targetOffset = invocation.getArgument(1);
			int maximum = invocation.getArgument(2);
			int copied = Math.min(maximum, firstKey + keyCount - nextKey.get());
			for (int i = 0; i < copied; i++) {
				target[targetOffset + i] = ValueIds.createId(ValueIds.T_URI, nextKey.getAndIncrement());
			}
			keys.addAndGet(copied);
			return copied;
		});
		when(adjacency.openKeyRunCursor()).thenReturn(keyCursor);
		NativeAdjacency.BoundRunCursor run = mock(NativeAdjacency.BoundRunCursor.class);
		AtomicLong key = new AtomicLong();
		when(run.bind(anyLong())).thenAnswer(invocation -> {
			key.set(invocation.getArgument(0));
			binds.incrementAndGet();
			long ordinal = ValueIds.getValue(key.get());
			if (ordinal < firstKey || ordinal >= firstKey + keyCount) {
				return 0L;
			}
			if (skewed) {
				return ordinal == 1L ? 4L : ordinal == 3_000L ? 2L : 3L;
			}
			return 3L;
		});
		when(run.copyNeighbors(anyLong(), anyInt(), any(long[].class), anyInt())).thenAnswer(invocation -> {
			long from = invocation.getArgument(0);
			int length = invocation.getArgument(1);
			long[] target = invocation.getArgument(2);
			int offset = invocation.getArgument(3);
			for (int i = 0; i < length; i++) {
				target[offset + i] = ValueIds.createId(ValueIds.T_URI,
						predicate * 100_000L + ValueIds.getValue(key.get()) * 10L + from + i);
			}
			neighbors.addAndGet(length);
			return length;
		});
		when(adjacency.openBoundRunCursor()).thenReturn(run);
		return adjacency;
	}
